function documentHtml(content, assets) {
  const replaced = content
    .replaceAll('__MARK__', assets.mark)
    .replaceAll('__WORDMARK__', assets.wordmark);
  return `<!doctype html><html><head><meta charset="utf-8"><style>${css(assets.fonts)}</style></head><body style="margin:0;width:1200px;height:800px;overflow:hidden"><div id="root">${replaced}</div></body></html>`;
}

